package in.agricred.farmerservice;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.time.Instant;import java.time.LocalDate;import java.math.BigDecimal;import java.util.*;import com.azure.storage.blob.*;import com.azure.storage.blob.models.BlobHttpHeaders;
@RestController @RequestMapping("/api/farmers") @CrossOrigin(origins="*") public class FarmerController{private final FarmerRepository repo;private final RepaymentRepository repaymentRepo;public FarmerController(FarmerRepository r,RepaymentRepository rr){repo=r;repaymentRepo=rr;}
@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","farmer-service");}
@GetMapping("/{email}") public ResponseEntity<?> get(@PathVariable String email){return repo.findByEmailIgnoreCase(email).<ResponseEntity<?>>map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}
@PostMapping public ResponseEntity<?> save(@RequestBody FarmerProfile p){if(p.email==null||p.email.isBlank())return ResponseEntity.badRequest().body(Map.of("error","Email is required")); FarmerProfile old=repo.findByEmailIgnoreCase(p.email).orElse(null);if(old!=null){p.id=old.id;p.landDocumentName=old.landDocumentName;p.landDocumentPath=old.landDocumentPath;}p.updatedAt=Instant.now();return ResponseEntity.ok(repo.save(p));}
@GetMapping public List<FarmerProfile> all(){return repo.findAll();}
public record RepaymentRequest(String email,String loanReference,LocalDate dueDate,LocalDate paymentDate,BigDecimal amountDue,BigDecimal amountPaid){}
@GetMapping("/{email}/repayments") public List<RepaymentRecord> repayments(@PathVariable String email){List<RepaymentRecord> rows=repaymentRepo.findByEmailIgnoreCaseOrderByDueDateDesc(email);rows.forEach(this::refreshStatus);repaymentRepo.saveAll(rows);syncProfileCounts(email,rows);return rows;}
@PostMapping("/{email}/repayments") public ResponseEntity<?> addRepayment(@PathVariable String email,@RequestBody RepaymentRequest r){if(r.loanReference()==null||r.loanReference().isBlank()||r.dueDate()==null||r.amountDue()==null||r.amountDue().compareTo(BigDecimal.ZERO)<=0||r.amountPaid()==null||r.amountPaid().compareTo(BigDecimal.ZERO)<0)return ResponseEntity.badRequest().body(Map.of("error","Loan reference, due date, positive amount due and non-negative amount paid are required"));if(r.amountPaid().compareTo(r.amountDue())>0)return ResponseEntity.badRequest().body(Map.of("error","Amount paid cannot exceed amount due for this instalment"));RepaymentRecord x=new RepaymentRecord();x.email=email;x.loanReference=r.loanReference().trim();x.dueDate=r.dueDate();x.paymentDate=r.paymentDate();x.amountDue=r.amountDue();x.amountPaid=r.amountPaid();refreshStatus(x);RepaymentRecord saved=repaymentRepo.save(x);List<RepaymentRecord> rows=repaymentRepo.findByEmailIgnoreCaseOrderByDueDateDesc(email);rows.forEach(this::refreshStatus);repaymentRepo.saveAll(rows);syncProfileCounts(email,rows);return ResponseEntity.ok(saved);}
private void syncProfileCounts(String email,List<RepaymentRecord> rows){FarmerProfile p=repo.findByEmailIgnoreCase(email).orElseGet(()->{FarmerProfile f=new FarmerProfile();f.email=email;return f;});p.latePayments=(int)rows.stream().filter(z->"LATE".equals(z.status)).count();p.onTimePayments=(int)rows.stream().filter(z->"ON_TIME".equals(z.status)).count();p.updatedAt=Instant.now();repo.save(p);}
private void refreshStatus(RepaymentRecord r){if(r.amountPaid!=null&&r.amountDue!=null&&r.amountPaid.compareTo(r.amountDue)>=0&&r.paymentDate!=null){r.status=r.paymentDate.isAfter(r.dueDate)?"LATE":"ON_TIME";}else if(LocalDate.now().isAfter(r.dueDate)){r.status="LATE";}else{r.status="PENDING";}}

@PostMapping(value="/{email}/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> upload(@PathVariable String email,@RequestParam("file") MultipartFile file){if(file.isEmpty())return ResponseEntity.badRequest().body(Map.of("error","Choose a file"));if(file.getSize()>10*1024*1024)return ResponseEntity.badRequest().body(Map.of("error","Maximum file size is 10 MB"));String original=Objects.requireNonNullElse(file.getOriginalFilename(),"document");String ext=original.toLowerCase();if(!(ext.endsWith(".pdf")||ext.endsWith(".png")||ext.endsWith(".jpg")||ext.endsWith(".jpeg")))return ResponseEntity.badRequest().body(Map.of("error","Only PDF, PNG or JPG files are accepted"));try{String safe=UUID.randomUUID()+"-"+Path.of(original).getFileName();String connection=System.getenv("AZURE_STORAGE_CONNECTION_STRING");String storedPath;if(connection!=null&&!connection.isBlank()){String container=System.getenv().getOrDefault("AZURE_STORAGE_CONTAINER","farmer-documents");BlobServiceClient service=new BlobServiceClientBuilder().connectionString(connection).buildClient();BlobContainerClient cc=service.getBlobContainerClient(container);if(!cc.exists())cc.create();BlobClient blob=cc.getBlobClient(safe);blob.upload(file.getInputStream(),file.getSize(),true);blob.setHttpHeaders(new BlobHttpHeaders().setContentType(Objects.requireNonNullElse(file.getContentType(),"application/octet-stream")));storedPath="azure://"+container+"/"+safe;}else{Path dir=Paths.get("uploads").toAbsolutePath();Files.createDirectories(dir);Path dest=dir.resolve(safe);Files.copy(file.getInputStream(),dest,StandardCopyOption.REPLACE_EXISTING);storedPath=dest.toString();}FarmerProfile p=repo.findByEmailIgnoreCase(email).orElseGet(()->{FarmerProfile x=new FarmerProfile();x.email=email;return x;});p.landDocumentName=original;p.landDocumentPath=storedPath;p.updatedAt=Instant.now();repo.save(p);return ResponseEntity.ok(Map.of("message","Document uploaded","fileName",original,"storage",storedPath.startsWith("azure://")?"Azure Blob Storage":"local"));}catch(Exception e){return ResponseEntity.internalServerError().body(Map.of("error","Upload failed; check storage configuration"));}}
}
